const domainPracticeQuestions = domainPracticeRows.map(([number, domain, objective, theme, difficulty, questionType, prompt, options, answer, explanationFr]) => {
  const legacySourceDomain = number <= 110 ? "1" : number <= 220 ? "2" : "3";
  const sourceDomain = number <= 310 ? legacySourceDomain : domain;
  return q(`dp-d${sourceDomain}-${String(number).padStart(3, "0")}`, domain, objective, FULL_DOMAIN_PRACTICE_PROMPTS[number] || prompt, options, answer, explanationFr, true, {
    sourceTitle: "Domain Practice",
    sourceSection: `Domain ${sourceDomain}`,
    domainPracticeTheme: theme,
    optionExplanations: FULL_DOMAIN_PRACTICE_OPTION_EXPLANATIONS[number],
    difficulty,
    questionType
  });
});

const rawQuestionBank = [...buildQuestionBank([...baseQuestions, ...guideQuestions]), ...practiceExamQuestions, ...supplementalStudyQuestions];
const questions = rawQuestionBank.filter(isQualityQuestion);
const activeQuestionIds = new Set(questions.map((question) => question.id));

