function CircularProgress({ percent, size = 54, strokeWidth = 5, tone = "ok" }) {
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;
  const offset = circumference - (percent / 100) * circumference;
  return e("div", { className: `circular-progress ${tone}`, style: { width: size, height: size } },
    e("svg", { width: size, height: size, viewBox: `0 0 ${size} ${size}` },
      e("circle", { className: "circle-bg", cx: size / 2, cy: size / 2, r: radius, strokeWidth }),
      e("circle", { className: "circle-progress", cx: size / 2, cy: size / 2, r: radius, strokeWidth, style: { strokeDasharray: circumference, strokeDashoffset: offset } })
    ),
    e("span", { className: "circle-label" }, `${percent}%`)
  );
}

