function readinessTone(score) {
  return score >= 75 ? "ok" : score >= 50 ? "warn" : "danger";
}

function modeHint(id) {
  const hints = { quiz: "Targeted QCM practice", pbq: "Hands-on scenarios", flashcards: "Acronyms and concepts", ports: "Fast protocol drill", weak: "Mistakes and low confidence", customExam: "Configurable timed tests", studyPlan: "Daily coach plan", readiness: "Final readiness signal" };
  return hints[id] || "Study mode";
}

function Metric({ label, value, isStreak }) {
  return e("article", { className: "metric" }, e("span", null, label), e("strong", { className: isStreak ? "streak-badge" : "" }, value));
}

function Badge({ label, tone = "neutral" }) {
  return e("span", { className: `badge ${tone}` }, label);
}

function ConfidenceSelector({ value = DEFAULT_CONFIDENCE, onChange, disabled = false, compact = false }) {
  return e("div", { className: `confidence-box ${compact ? "compact" : ""}` },
    e("span", null, "Confidence"),
    e("div", { className: "confidence-options" }, CONFIDENCE_LEVELS.map((level) => e("button", {
      key: level.id,
      type: "button",
      disabled,
      className: value === level.id ? `active ${level.tone}` : "",
      onClick: () => onChange(level.id)
    }, level.label)))
  );
}

function OptionRationales({ question }) {
  const rationales = buildOptionRationales(question);
  if (!rationales.length) return null;
  return e("div", { className: "option-rationales" },
    e("strong", null, "Why each option"),
    rationales.map((item) => e("div", { className: `option-rationale ${item.correct ? "correct" : "wrong"}`, key: `${item.letter}-${item.option}` },
      e(Badge, { label: item.letter, tone: item.correct ? "ok" : "neutral" }),
      e("div", null, e("b", null, item.option), e("p", null, item.rationale))
    ))
  );
}

