    pbq18: ["5", "5.4"],
    pbq20: ["2", "2.4"],
    pbq21: ["4", "4.1"],
    pbq22: ["5", "5.2"],
    pbq24: ["3", "3.4"],
    pbq25: ["5", "5.1"],
    pbq26: ["3", "3.2"],
    pbq27: ["4", "4.1"],
    pbq28: ["2", "2.4"],
    pbq29: ["3", "3.1"],
    pbq30: ["1", "1.2"],
    pbq31: ["1", "1.2"],
    pbq32: ["4", "4.3"],
    pbq33: ["3", "3.1"],
    pbq34: ["3", "3.1"],
    pbq35: ["2", "2.2"],
    pbq36: ["2", "2.4"],
    pbq37: ["4", "4.8"],
    pbq38: ["3", "3.2"],
    pbq39: ["5", "5.1"],
    pbq40: ["3", "3.1"],
    pbq41: ["4", "4.3"],
