    pbq44: ["5", "5.3"],
    pbq45: ["3", "3.4"],
    pbq46: ["4", "4.8"],
    pbq47: ["2", "2.1"],
    pbq48: ["5", "5.1"],
    pbq49: ["4", "4.1"],
    pbq50: ["3", "3.1"],
    "pe-pbq-sqli": ["2", "2.4"],
    "pe-pbq-mfa": ["4", "4.6"],
    "pe-pbq-cloud-bucket": ["3", "3.3"],
    "pe-pbq-physical": ["1", "1.2"],
    "pe-pbq-firewall-ssh": ["4", "4.5"],
